{
  "sop_id": "SOP-021",
  "title": "Employee Document Verification",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create ticket and assign to self",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Check checklist completeness and document legibility",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Verify identity and address proofs",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Send education and employment confirmations",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Cross-check documents against offer letter and HRMS",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S6",
      "name": "Record verification status and submit",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "A1",
      "name": "Incharge approval",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Correct and resubmit on rejection",
      "role": "Executor",
      "type": "rework"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always",
      "evidence": "Document checks | Activity | Executor | Incharge | Lead | Issuer / BGV agency |---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|"
    },
    {
      "stage": "Lead",
      "condition": "discrepancies only",
      "evidence": "Approval | Activity | Executor | Incharge | Lead | Issuer / BGV agency |---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Issuer / BGV agency",
      "item": "Credential confirmation",
      "parallel_group": "P1",
      "evidence": "Credential confirmation (D1) | Activity | Executor | Incharge | Lead | Issuer / BGV agency |---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|"
    }
  ],
  "rework_reasons": [
    "Required document missing",
    "Incorrect category",
    "Amount mismatch",
    "Wrong quantity"
  ],
  "first_pass_yield_target": 0.9
}
